import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig({ base: './', plugins: [vue()] })

import { createRouter, createWebHashHistory } from 'vue-router'
import HomeView from '../views/HomeView.vue'
import AboutView from '../views/AboutView.vue'

export default createRouter({
  history: createWebHashHistory(),
  routes: [
    { path: '/', component: HomeView },
    { path: '/about', component: AboutView }
  ]
})

:root { font-family: Inter, system-ui, sans-serif; color: #172033; background: #f7f8fc; }
* { box-sizing: border-box; }
body { margin: 0; }
a { color: inherit; }
.shell { min-height: 100vh; display: grid; grid-template-rows: auto 1fr auto; }
header { height: 72px; display: flex; align-items: center; justify-content: space-between; padding: 0 max(24px, calc((100% - 1100px) / 2)); background: #fff; border-bottom: 1px solid #e7eaf0; }
.brand { font-weight: 800; text-decoration: none; }
nav { display: flex; gap: 24px; }
nav a { text-decoration: none; color: #667085; }
nav a.router-link-active { color: #3157d5; }
main { width: min(1100px, calc(100% - 40px)); margin: 0 auto; }
.hero, .page { padding: 100px 0 72px; max-width: 720px; }
.eyebrow { color: #3157d5; font-weight: 700; letter-spacing: .08em; }
h1 { margin: 12px 0 20px; font-size: clamp(2.4rem, 7vw, 4.5rem); line-height: 1.05; }
p { line-height: 1.8; color: #5b6475; }
.button { display: inline-block; margin-top: 20px; padding: 12px 20px; border-radius: 9px; background: #3157d5; color: #fff; text-decoration: none; }
.features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; padding-bottom: 72px; }
.features article { padding: 24px; background: #fff; border-radius: 14px; border: 1px solid #e7eaf0; }
footer { padding: 28px; text-align: center; color: #8a93a3; }
@media (max-width: 680px) { .features { grid-template-columns: 1fr; } header { padding: 0 20px; } }
